import {clone} from '../document/model.js';
export const easing={hold:()=>0,linear:t=>t,easeIn:t=>t*t,easeOut:t=>1-(1-t)**2,easeInOut:t=>t<.5?2*t*t:1-(-2*t+2)**2/2};
function rgb(c){if(/^#[0-9a-f]{3}$/i.test(c))c='#'+[...c.slice(1)].map(x=>x+x).join('');return /^#[0-9a-f]{6}$/i.test(c)?[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)):null;}
export function compatible(a,b){return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((n,i)=>!!n.move===!!b[i].move&&!!n.close===!!b[i].close&&['in','out'].every(k=>!!n[k]===!!b[i][k]));}
export function interpolate(a,b,t){if(typeof a==='number'&&typeof b==='number')return a+(b-a)*t;if(typeof a==='string'){const ca=rgb(a),cb=rgb(b);if(ca&&cb)return '#'+ca.map((v,i)=>Math.round(v+(cb[i]-v)*t).toString(16).padStart(2,'0')).join('');}if(a?.points&&b?.points&&a.rows===b.rows&&a.cols===b.cols)return {...clone(a),bounds:Object.fromEntries(['x','y','width','height'].map(k=>[k,interpolate(a.bounds[k],b.bounds[k],t)])),points:a.points.map((p,i)=>({x:interpolate(p.x,b.points[i].x,t),y:interpolate(p.y,b.points[i].y,t),color:interpolate(p.color,b.points[i].color,t)}))};if(compatible(a,b))return a.map((n,i)=>{const o={...n,x:interpolate(n.x,b[i].x,t),y:interpolate(n.y,b[i].y,t)};for(const k of ['in','out'])if(n[k])o[k]={x:interpolate(n[k].x,b[i][k].x,t),y:interpolate(n[k].y,b[i][k].y,t)};return o;});return clone(t<1?a:b);}
export function evaluateTrack(track,time,base){if(!track?.length)return base;if(time<=track[0].time)return clone(track[0].value);for(let i=1;i<track.length;i++){const b=track[i],a=track[i-1];if(time<b.time){const t=(time-a.time)/(b.time-a.time);return interpolate(a.value,b.value,(easing[a.easing]||easing.linear)(t));}}return clone(track.at(-1).value);}
export function evaluated(n,time){const result={...n};for(const [p,t] of Object.entries(n.tracks||{}))result[p]=evaluateTrack(t,time,n[p]);return result;}
export function putKey(n,prop,time,value,ease='easeInOut'){const track=n.tracks[prop]||=[];let key=track.find(k=>Math.abs(k.time-time)<.00001);if(key){key.value=clone(value);}else{key={id:globalThis.crypto.randomUUID(),time,value:clone(value),easing:ease};track.push(key);}track.sort((a,b)=>a.time-b.time);return key;}
export function enableTrack(n,prop,time,ease='easeInOut'){const value=clone(evaluated(n,time)[prop]);if(!n.tracks[prop]?.length&&time>0)putKey(n,prop,0,n[prop],ease);return putKey(n,prop,time,value,ease);}
export function setProperty(n,prop,value,time){if(prop==='nodes'&&!n.tracks.nodes?.length&&Object.values(n.tracks).some(t=>t.length)){putKey(n,'nodes',0,n.nodes);}if(n.tracks[prop]?.length)putKey(n,prop,time,value);else n[prop]=value;}
